def investigate(context, acquire):
    spans = acquire("spans")
    population = acquire("population")

    def interval_union(intervals):
        if not intervals:
            return 0.0
        ordered = sorted(intervals)
        total = 0.0
        cur_start = ordered[0][0]
        cur_end = ordered[0][1]
        for start, end in ordered[1:]:
            if start > cur_end:
                total += cur_end - cur_start
                cur_start = start
                cur_end = end
            else:
                if end > cur_end:
                    cur_end = end
        total += cur_end - cur_start
        return total

    def request_quantity(rows, billed):
        if billed:
            return sum(row["t1"] - row["t0"] for row in rows)
        intervals = []
        for row in rows:
            intervals.append((row["t0"], row["t1"]))
        return interval_union(intervals)

    periods = ["before", "after"]
    by_period = {}
    for period in periods:
        by_period[period] = [row for row in spans if row["period"] == period]

    unresolved = []
    findings = []

    # duplicate_delivery: identical operation record appears more than once
    seen = set()
    duplicate = False
    for row in spans:
        key = (row["period"], row["rid"], row["sid"], row["cohort"], row["t0"], row["t1"])
        if key in seen:
            duplicate = True
        seen.add(key)
    if duplicate:
        findings.append("duplicate_delivery")

    # conflicting_event: same operation ID with conflicting records within a period
    op_records = {}
    for row in spans:
        key = (row["period"], row["sid"])
        rec = (row["rid"], row["cohort"], row["t0"], row["t1"])
        if key in op_records:
            if op_records[key] != rec:
                if "conflicting_event" not in unresolved:
                    unresolved.append("conflicting_event")
        else:
            op_records[key] = rec

    # unknown_clock_unit
    units = context.get("clock_units", {})
    for period in periods:
        unit = units.get(period)
        if unit is None or str(unit).strip().lower() in ("", "unknown", "none"):
            if "unknown_clock_unit" not in unresolved:
                unresolved.append("unknown_clock_unit")

    # population proportions and coverage
    pop_counts = {}
    for row in population:
        pop_counts[(row["period"], row["class"])] = row["count"]

    observed_rids = {}
    for period in periods:
        for row in by_period[period]:
            observed_rids.setdefault((period, row["cohort"]), set()).add(row["rid"])

    incomplete = False
    for period in periods:
        classes = set()
        for row in population:
            if row["period"] == period:
                classes.add(row["class"])
        for cls in classes:
            expected = pop_counts.get((period, cls), 0)
            observed = len(observed_rids.get((period, cls), set()))
            if observed != expected:
                incomplete = True
    if incomplete:
        if "incomplete_coverage" not in unresolved:
            unresolved.append("incomplete_coverage")

    # workload_shift: population class proportions differ between periods
    before_classes = set(r["class"] for r in population if r["period"] == "before")
    after_classes = set(r["class"] for r in population if r["period"] == "after")
    before_total = sum(pop_counts.get(("before", c), 0) for c in before_classes)
    after_total = sum(pop_counts.get(("after", c), 0) for c in after_classes)
    all_classes = before_classes | after_classes
    shift = False
    if before_total > 0 and after_total > 0:
        for cls in all_classes:
            pb = pop_counts.get(("before", cls), 0) / before_total
            pa = pop_counts.get(("after", cls), 0) / after_total
            if abs(pb - pa) > 1e-8:
                shift = True
    if shift:
        findings.append("workload_shift")

    # If unresolved, ratio null and no latency conclusion
    if unresolved:
        return {"findings": findings, "unresolved": unresolved, "ratio": None}

    # Determine requested quantity from contract
    contract = str(context.get("quantity_contract", "")).lower()
    billed = "billed" in contract or "worker time" in contract

    # Compute per-request quantities
    request_quantities = {}
    for period in periods:
        rids = set(row["rid"] for row in by_period[period])
        for rid in rids:
            rows = [row for row in by_period[period] if row["rid"] == rid]
            request_quantities[(period, rid)] = request_quantity(rows, billed)

    # Standardize using BEFORE population proportions over classes in BOTH periods
    weights = {}
    for cls in before_classes:
        weights[cls] = pop_counts.get(("before", cls), 0) / before_total if before_total > 0 else 0.0

    def class_of(rid, rows):
        for row in rows:
            if row["rid"] == rid:
                return row["cohort"]
        return None

    def standardized_mean(period):
        total = 0.0
        for cls in before_classes:
            rids = [rid for rid in set(row["rid"] for row in by_period[period]) if class_of(rid, by_period[period]) == cls]
            if rids:
                class_mean = sum(request_quantities[(period, rid)] for rid in rids) / len(rids)
            else:
                class_mean = 0.0
            total += weights[cls] * class_mean
        return total

    before_mean = standardized_mean("before")
    after_mean = standardized_mean("after")

    if before_mean == 0:
        return {"findings": findings, "unresolved": unresolved, "ratio": None}

    ratio = after_mean / before_mean

    if ratio > 1.2 + 1e-8:
        findings.append("latency_regression")
    elif ratio < 0.8 - 1e-8:
        findings.append("latency_improvement")
    else:
        findings.append("latency_stable")

    return {"findings": findings, "unresolved": unresolved, "ratio": ratio}

