def investigate(context, acquire):
    spans = acquire("spans")
    population = acquire("population")

    def merge_intervals(intervals):
        if not intervals:
            return 0.0
        ordered = sorted(intervals)
        total = 0.0
        cur_start = ordered[0][0]
        cur_end = ordered[0][1]
        for start, end in ordered[1:]:
            if start > cur_end:
                total += cur_end - cur_start
                cur_start = start
                cur_end = end
            else:
                if end > cur_end:
                    cur_end = end
        total += cur_end - cur_start
        return total

    def period_units(period):
        units = context.get("clock_units", {})
        if isinstance(units, dict):
            return units.get(period)
        return None

    unresolved = []
    findings = []

    before_unit = period_units("before")
    after_unit = period_units("after")
    if before_unit is None or after_unit is None or before_unit != after_unit:
        unresolved.append("unknown_clock_unit")

    seen = {}
    duplicate = False
    conflicting = False
    for row in spans:
        key = (row["period"], row["sid"])
        rec = (row["rid"], row["cohort"], row["t0"], row["t1"])
        if key in seen:
            if seen[key] == rec:
                duplicate = True
            else:
                conflicting = True
        else:
            seen[key] = rec
    if duplicate:
        findings.append("duplicate_delivery")
    if conflicting:
        unresolved.append("conflicting_event")

    pop = {}
    for row in population:
        pop.setdefault(row["period"], {})[row["class"]] = row["count"]

    before_props = {}
    after_props = {}
    for period, target in (("before", before_props), ("after", after_props)):
        classes = pop.get(period, {})
        total = sum(classes.values())
        for cls in classes:
            target[cls] = classes[cls] / total if total else 0.0

    if before_props != after_props:
        findings.append("workload_shift")

    observed = {}
    for row in spans:
        observed.setdefault(row["period"], {}).setdefault(row["cohort"], set()).add(row["rid"])

    incomplete = False
    for period in ("before", "after"):
        for cls, count in pop.get(period, {}).items():
            if len(observed.get(period, {}).get(cls, set())) != count:
                incomplete = True
    if incomplete:
        unresolved.append("incomplete_coverage")

    ratio = None
    if not unresolved:
        per_request = {}
        for row in spans:
            key = (row["period"], row["rid"])
            per_request.setdefault(key, []).append((row["t0"], row["t1"]))

        class_means = {}
        for period in ("before", "after"):
            by_class = {}
            for (p, rid), intervals in per_request.items():
                if p != period:
                    continue
                cls = None
                for row in spans:
                    if row["period"] == period and row["rid"] == rid:
                        cls = row["cohort"]
                        break
                by_class.setdefault(cls, []).append(merge_intervals(intervals))
            class_means[period] = {}
            for cls, vals in by_class.items():
                class_means[period][cls] = sum(vals) / len(vals)

        before_std = 0.0
        after_std = 0.0
        for cls, prop in before_props.items():
            before_std += prop * class_means["before"].get(cls, 0.0)
            after_std += prop * class_means["after"].get(cls, 0.0)

        if before_std == 0:
            unresolved.append("incomplete_coverage")
        else:
            ratio = after_std / before_std
            if ratio > 1.2 + 1e-8:
                findings.append("latency_regression")
            elif ratio < 0.8 - 1e-8:
                findings.append("latency_improvement")
            else:
                findings.append("latency_stable")

    return {"findings": findings, "unresolved": unresolved, "ratio": ratio}

