    population = acquire("population")

    def interval_union(intervals):
        if not intervals:
            return 0.0
        ordered = sorted(intervals)
        total = 0.0
        cur_start = ordered[0][0]
        cur_end = ordered[0][1]
        for start, end in ordered[1:]:
            if start > cur_end:
                total += cur_end - cur_start
                cur_start = start
                cur_end = end
            else:
                if end > cur_end:
                    cur_end = end
        total += cur_end - cur_start
        return total

    def request_quantity(rows, mode):
        if mode == "union":
            intervals = []
            for row in rows:
                intervals.append((row["t0"], row["t1"]))
            return interval_union(intervals)
        if mode == "sum":
            total = 0.0
            for row in rows:
                total += row["t1"] - row["t0"]
            return total
        starts = []
        ends = []
        for row in rows:
            starts.append(row["t0"])
            ends.append(row["t1"])
        return max(ends) - min(starts)

    contract = str(context.get("quantity_contract", "")).lower()
    if "billed" in contract or "full duration" in contract or "every distinct" in contract:
        mode = "sum"
    elif "first" in contract and "last" in contract:
        mode = "span"
    else:
        mode = "union"

    periods = ["before", "after"]
    classes = []
    for row in population:
        cls = row["class"]
        if cls not in classes:
            classes.append(cls)

    pop = {}
    for row in population:
        pop.setdefault(row["period"], {})[row["class"]] = row["count"]

