        if key in seen:
            if seen[key] == rec:
                duplicate = True
            else:
                conflicting = True
        else:
            seen[key] = rec

    if conflicting:
        unresolved.append("conflicting_event")

    observed = {}
    for row in spans:
        observed.setdefault(row["period"], {}).setdefault(row["cohort"], set()).add(row["rid"])

    incomplete = False
    for period in periods:
        for cls in classes:
            expected_count = pop.get(period, {}).get(cls, 0)
            actual_count = len(observed.get(period, {}).get(cls, set()))
            if actual_count != expected_count:
                incomplete = True
    if incomplete:
        unresolved.append("incomplete_coverage")

    findings = []
    if duplicate:
        findings.append("duplicate_delivery")

    workload_shift = False
    for cls in classes:
        before_share = pop.get("before", {}).get(cls, 0)
        after_share = pop.get("after", {}).get(cls, 0)
        if before_share != after_share:
            workload_shift = True
    if workload_shift:
        findings.append("workload_shift")

    ratio = None
    if not unresolved:
        by_period = {}
        for row in spans:
            by_period.setdefault(row["period"], {}).setdefault(row["rid"], []).append(row)

        class_means = {}
        for period in periods:
            class_means[period] = {}
            for cls in classes:
                rids = observed.get(period, {}).get(cls, set())
                vals = []
                for rid in rids:
                    rows = by_period.get(period, {}).get(rid, [])
                    if rows:
                        vals.append(request_quantity(rows, mode))
                if vals:
                    class_means[period][cls] = sum(vals) / len(vals)

        before_total = sum(pop.get("before", {}).values())

        before_std = 0.0
        after_std = 0.0
        for cls in classes:
            if cls in class_means["before"] and cls in class_means["after"]:
                w = pop.get("before", {}).get(cls, 0) / before_total
                before_std += w * class_means["before"][cls]
                after_std += w * class_means["after"][cls]

        if before_std != 0:
            ratio = after_std / before_std
            if ratio > 1.2 + 1e-8:
                findings.append("latency_regression")
            elif ratio < 0.8 - 1e-8:
                findings.append("latency_improvement")
            else:
                findings.append("latency_stable")

    return {"findings": findings, "unresolved": unresolved, "ratio": ratio}

